function courseState(){if(!ST.courseV2||ST.courseV2.version!==2)ST.courseV2={version:2,done:{},sessions:{}};var v=ST.courseV2;if(!v.done||typeof v.done!=='object'||Array.isArray(v.done))v.done={};if(!v.sessions||typeof v.sessions!=='object'||Array.isArray(v.sessions))v.sessions={};if(v.session&&v.session.l&&!v.sessions[v.session.l]){v.sessions[v.session.l]=v.session;delete v.session;}return v;}
